from pptx import Presentation
from pathlib import Path
ppt=Presentation('assets/ppt_pack/75315785_Ce掺杂Co3O4亚氯酸盐高级氧化.pptx')
for i,slide in enumerate(ppt.slides, start=1):
    texts=[]
    for shape in slide.shapes:
        if hasattr(shape, 'text'):
            t=shape.text.strip()
            if t:
                texts.append(t.replace('\n',' | '))
    print(f'--- Slide {i} ---')
    print(' || '.join(texts[:10]))
    print()
